#include <iostream>
#include <vector>
#include <cassert>
#include <cmath>
#include <algorithm>
using namespace std;

using i64 = long long;
using pii = pair<int, int>;
using pll = pair<i64, i64>;

constexpr double EPS = 1e-7;
constexpr i64 INF = 1000000000;
constexpr double PI = acos(-1.0);
constexpr i64 MOD = 1000000007;

i64 N, K;

template<typename T>
class Matrix {
public:
    vector<vector<T>> A;

    Matrix() {}

    Matrix(size_t n, size_t m) : A(n, vector<T>(m, 0)) {}

    Matrix(size_t n) : A(n, vector<T>(n, 0)) {}

    size_t n_rows() const { return A.size(); }
    size_t n_cols() const { return A.empty() ? 0 : A[0].size(); }

    const vector<T>& operator[](size_t idx) const { return A[idx]; }
    vector<T>& operator[](size_t idx) { return A[idx]; }

    static Matrix identity(size_t n) {
        Matrix mat(n);
        for (size_t i = 0; i < n; ++i) mat[i][i] = 1;
        return mat;
    }

    Matrix& operator+=(const Matrix& other) {
        assert(n_rows() == other.n_rows() && n_cols() == other.n_cols());
        for (size_t i = 0; i < n_rows(); ++i)
            for (size_t j = 0; j < n_cols(); ++j)
                A[i][j] = (A[i][j] + other[i][j]) % MOD;
        return *this;
    }

    Matrix& operator-=(const Matrix& other) {
        assert(n_rows() == other.n_rows() && n_cols() == other.n_cols());
        for (size_t i = 0; i < n_rows(); ++i)
            for (size_t j = 0; j < n_cols(); ++j)
                A[i][j] = (A[i][j] - other[i][j] + MOD) % MOD;
        return *this;
    }

    Matrix& operator*=(const Matrix& other) {
        size_t r1 = n_rows(), c1 = n_cols(), c2 = other.n_cols();
        assert(c1 == other.n_rows());
        vector<vector<T>> res(r1, vector<T>(c2, 0));
        for (size_t i = 0; i < r1; ++i)
            for (size_t k = 0; k < c1; ++k)
                for (size_t j = 0; j < c2; ++j)
                    res[i][j] = (res[i][j] + A[i][k] * other[k][j]) % MOD;
        A = move(res);
        return *this;
    }

    Matrix& operator^=(i64 exp) {
        Matrix res = identity(n_rows());
        Matrix base = *this;
        while (exp > 0) {
            if (exp & 1) res *= base;
            base *= base;
            exp >>= 1;
        }
        A = move(res.A);
        return *this;
    }

    Matrix operator+(const Matrix& other) const { Matrix tmp(*this); tmp += other; return tmp; }
    Matrix operator-(const Matrix& other) const { Matrix tmp(*this); tmp -= other; return tmp; }
    Matrix operator*(const Matrix& other) const { Matrix tmp(*this); tmp *= other; return tmp; }
    Matrix operator^(i64 exp) const { Matrix tmp(*this); tmp ^= exp; return tmp; }

    friend ostream& operator<<(ostream& os, const Matrix& m) {
        for (size_t i = 0; i < m.n_rows(); ++i) {
            os << "[";
            for (size_t j = 0; j < m.n_cols(); ++j) {
                os << m[i][j] << (j + 1 == m.n_cols() ? "]\n" : ",");
            }
        }
        return os;
    }

    T determinant() {
        Matrix<T> B(*this);
        assert(n_rows() == n_cols());
        T det = 1;
        size_t n = n_rows();
        for (size_t i = 0; i < n; ++i) {
            int pivot = -1;
            for (size_t j = i; j < n; ++j) {
                if (B[j][i] != 0) {
                    pivot = j;
                    break;
                }
            }
            if (pivot == -1) return 0;
            if (i != pivot) {
                det = (det * (MOD - 1)) % MOD;
                swap(B[i], B[pivot]);
            }
            det = (det * B[i][i]) % MOD;
            T inv = modinv(B[i][i], MOD);
            for (size_t j = 0; j < n; ++j) {
                B[i][j] = (B[i][j] * inv) % MOD;
            }
            for (size_t j = i + 1; j < n; ++j) {
                T factor = B[j][i];
                for (size_t k = 0; k < n; ++k) {
                    B[j][k] = (B[j][k] - B[i][k] * factor) % MOD;
                    if (B[j][k] < 0) B[j][k] += MOD;
                }
            }
        }
        return (det % MOD + MOD) % MOD;
    }

private:
    T modinv(T a, T mod) {
        T m = mod, x = 0, y = 1;
        if (mod == 1) return 0;
        while (a > 1) {
            T q = a / mod;
            T t = mod;
            mod = a % mod;
            a = t;
            t = x;
            x = y - q * x;
            y = t;
        }
        if (y < 0) y += m;
        return y;
    }

public:
    void rotate() {
        Matrix<T> temp(n_rows());
        for (size_t i = 0; i < K; ++i) {
            for (size_t j = 0; j < K; ++j) {
                temp[i][j] = A[(i + K - 1) % K][(j + K - 1) % K];
            }
            temp[i][K] = A[(i + K - 1) % K][K];
            temp[K][i] = A[K][(i + K - 1) % K];
        }
        temp[K][K] = A[K][K];
        A = move(temp.A);
    }
};

Matrix<i64> mat[70][35];

i64 ipow(i64 base, i64 exp) {
    if (exp == 0) return 1;
    i64 res = ipow(base, exp / 2);
    res = (res * res) % MOD;
    if (exp & 1) res = (res * base) % MOD;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N >> K;

    i64 depth = 0;
    i64 tmp = N;
    while (tmp >= K) {
        depth++;
        tmp /= K;
    }

    mat[0][0] = Matrix<i64>::identity(K + 1);
    for (int i = 1; i < K + 1; ++i) mat[0][0][0][i] = 1;

    for (int i = 1; i < K; ++i) {
        mat[0][i] = mat[0][i-1];
        mat[0][i].rotate();
    }

    for (i64 idx = 1; idx <= depth; ++idx) {
        mat[idx][0] = mat[idx-1][0];
        for (int i = 1; i < K; ++i) {
            mat[idx][0] = mat[idx-1][i] * mat[idx][0];
        }
        for (int i = 1; i < K; ++i) {
            mat[idx][i] = mat[idx][i-1];
            mat[idx][i].rotate();
        }
    }

    Matrix<i64> ans(K + 1, 1);
    ans[K][0] = 1;
    int offset = 0;

    while (depth >= 0) {
        for (int i = 0; ; ++i) {
            if (ipow(K, depth) <= N) {
                N -= ipow(K, depth);
                ans = mat[depth][offset] * ans;
                offset = (offset + 1) % K;
            } else {
                break;
            }
        }
        depth--;
    }

    i64 total = 0;
    for (int i = 0; i < K + 1; ++i) {
        total = (total + ans[i][0]) % MOD;
    }
    cout << total << '\n';

    return 0;
}
